// Launch Radar — Peer-Calibrated Pre-Token Valuation & Farm Planner UI
// Zero frameworks, zero network calls. Reads window.RADAR_DATA generated by main.ts.

(() => {
  'use strict';

  const DATA = window.RADAR_DATA;
  const ROOT = document.getElementById('app');

  if (!DATA || !Array.isArray(DATA.rows)) {
    ROOT.innerHTML = '<div class="empty-state"><h2>No snapshot data loaded</h2><p>Run main.ts to generate data.js alongside this dashboard.</p></div>';
    return;
  }

  const L2_CHAINS = new Set([
    'Base', 'Arbitrum', 'Optimism', 'Scroll', 'Ink', 'Monad', 'Unichain', 'Linea',
    'Blast', 'Mantle', 'Polygon', 'Polygon zkEVM', 'zkSync Era', 'Mode', 'BOB',
    'Sonic', 'Berachain', 'Katana', 'Plasma', 'Morph', 'Taiko', 'Soneium', 'World Chain',
    'Fraxtal', 'Starknet', 'Manta', 'Metis', 'Corn', 'MegaETH', 'Etherlink', 'Abstract',
  ]);
  const ALT_L1_CHAINS = new Set([
    'Solana', 'Sui', 'Aptos', 'Tron', 'Avalanche', 'Binance', 'Hyperliquid L1',
    'Sei', 'Near', 'TON', 'Stellar', 'Flare', 'Bittensor', 'Cardano', 'Cosmos',
    'Algorand', 'Hedera', 'Injective', 'Osmosis', 'Cronos', 'Kava', 'Celo',
  ]);

  const qs = new URLSearchParams(window.location.search);
  const state = {
    view: ['radar', 'live', 'model'].includes(qs.get('view')) ? qs.get('view') : 'radar',
    tier: ['all', 'watchlist', 'early'].includes(qs.get('tier')) ? qs.get('tier') : 'all',
    search: qs.get('q') || '',
    category: qs.get('cat') || 'all',
    chain: qs.get('chain') || 'all',
    momentum: ['all', 'pos', 'fast', 'neg'].includes(qs.get('momentum')) ? qs.get('momentum') : 'all',
    sortKey: qs.get('sort') || 'rank',
    sortDir: qs.get('dir') === 'desc' ? 'desc' : 'asc',
    selectedSlug: qs.get('detail') || null,
    sandboxOpen: qs.get('sandbox') === '1',
    params: { ...DATA.params },
  };

  function clamp(v, lo, hi) {
    return Math.min(hi, Math.max(lo, v));
  }

  function round4(n) {
    return Math.round(n * 1e4) / 1e4;
  }

  function esc(str) {
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function fmtUsd(n) {
    if (n === null || n === undefined || !Number.isFinite(n)) return '—';
    const abs = Math.abs(n);
    if (abs >= 1e9) return `$${(n / 1e9).toFixed(2)}B`;
    if (abs >= 1e6) return `$${(n / 1e6).toFixed(1)}M`;
    if (abs >= 1e3) return `$${(n / 1e3).toFixed(0)}K`;
    return `$${Math.round(n)}`;
  }

  function fmtPct(v) {
    if (v === null || v === undefined || !Number.isFinite(v)) return 'Unreported';
    return `${v >= 0 ? '+' : ''}${v.toFixed(1)}%`;
  }

  function fmtAge(days) {
    if (days === null || days === undefined) return 'N/A';
    if (days >= 365) return `${(days / 365).toFixed(1)}y`;
    return `${days}d`;
  }

  function quantile(sorted, q) {
    if (!sorted.length) return 0;
    const pos = (sorted.length - 1) * q;
    const lo = Math.floor(pos);
    const hi = Math.ceil(pos);
    return lo === hi ? sorted[lo] : sorted[lo] + (sorted[hi] - sorted[lo]) * (pos - lo);
  }

  /** Re-calibrate category multiples from live peers when the user adjusts shrinkage_k in the sandbox. */
  function calibrateCategoryMultiples(livePeers, params) {
    const byCat = new Map();
    const all = [];
    for (const p of livePeers) {
      const r = p.mcap_tvl_ratio;
      if (!Number.isFinite(r) || r <= 0) continue;
      const cat = p.category || 'Other';
      if (!byCat.has(cat)) byCat.set(cat, []);
      byCat.get(cat).push(r);
      all.push(r);
    }
    all.sort((a, b) => a - b);
    const gMed = all.length ? quantile(all, 0.5) : DATA.calibration.global_median;
    const gP25 = all.length ? quantile(all, 0.25) : DATA.calibration.global_p25;
    const gP75 = all.length ? quantile(all, 0.75) : DATA.calibration.global_p75;
    const k = params.shrinkage_k;
    const categories = {};
    for (const [cat, vals] of byCat.entries()) {
      vals.sort((a, b) => a - b);
      const n = vals.length;
      const med = quantile(vals, 0.5);
      const p25 = quantile(vals, 0.25);
      const p75 = quantile(vals, 0.75);
      const logShrink = (val, prior, lo, hi) => {
        const blended = Math.exp((n * Math.log(clamp(val, 0.04, 1.5)) + k * Math.log(clamp(prior, 0.04, 1.5))) / (n + k));
        return clamp(blended, lo, hi);
      };
      const base = logShrink(med, gMed, params.multiple_min, params.multiple_max);
      const bear = logShrink(p25, gP25, params.multiple_min * 0.45, base * 0.92);
      const bull = logShrink(p75, gP75, base * 1.15, params.multiple_max * 2.2);
      categories[cat] = {
        category: cat,
        peer_count: n,
        raw_median: round4(med),
        base_multiple: round4(base),
        bear_multiple: round4(bear),
        bull_multiple: round4(bull),
      };
    }
    return {
      live_peer_count: all.length,
      global_median: round4(gMed),
      global_p25: round4(gP25),
      global_p75: round4(gP75),
      categories,
    };
  }

  /** Mirror of lib/model.ts computeImpliedValue so sandbox edits match server valuation identically. */
  function computeImpliedValue(row, cal, params) {
    const catCal = cal.categories[row.category || 'Other'];
    const baseMultiple = catCal ? catCal.base_multiple : clamp(cal.global_median, params.multiple_min, params.multiple_max);
    const bearMultiple = catCal ? catCal.bear_multiple : clamp(cal.global_p25, params.multiple_min * 0.45, baseMultiple * 0.92);
    const bullMultiple = catCal ? catCal.bull_multiple : clamp(cal.global_p75, baseMultiple * 1.15, params.multiple_max * 2.2);
    const rawGrowth = typeof row.change_7d === 'number' && Number.isFinite(row.change_7d) ? row.change_7d : 0;
    const growthMult = 1 + params.growth_weight * Math.tanh(rawGrowth / params.growth_scale);
    const effectiveAge = row.age_days === null ? params.unknown_age_days : row.age_days;
    const matRatio = clamp(effectiveAge, 0, params.maturity_days) / params.maturity_days;
    const maturityMult = params.maturity_floor + params.maturity_range * Math.sqrt(matRatio);
    const chainCount = Math.max(1, row.chains.length);
    const chainMult = 1 + params.chain_weight * Math.min(Math.log(chainCount), params.chain_log_cap);
    const composite = growthMult * maturityMult * chainMult;
    const implied = Math.max(1, Math.round(row.tvl_usd * baseMultiple * composite));
    const bear = Math.max(1, Math.min(implied, Math.round(row.tvl_usd * bearMultiple * composite)));
    const bull = Math.max(implied, Math.round(row.tvl_usd * bullMultiple * composite));
    return {
      ...row,
      implied_value_usd: implied,
      bear_value_usd: bear,
      bull_value_usd: bull,
      base_multiple: round4(baseMultiple),
      bear_multiple: round4(bearMultiple),
      bull_multiple: round4(bullMultiple),
      peer_count: catCal ? catCal.peer_count : 0,
      growth_multiplier: round4(growthMult),
      maturity_multiplier: round4(maturityMult),
      chain_multiplier: round4(chainMult),
    };
  }

  /** Mirror of lib/model.ts buildFarmPlan for the protocol detail drawer. */
  function buildFarmPlan(row) {
    const chains = row.chains || [];
    const lowFee = chains.find((c) => c !== 'Ethereum' && (L2_CHAINS.has(c) || ALT_L1_CHAINS.has(c)));
    const primary = lowFee || chains[0] || 'its primary chain';
    const secondary = chains.find((c) => c !== primary) || null;
    const gasTier = primary === 'Ethereum' ? 'mainnet' : ALT_L1_CHAINS.has(primary) ? 'alt-l1' : 'l2';
    const gas = gasTier === 'mainnet'
      ? { setup: 12, weekly: 4, total: 28, label: '$10-$15 Ethereum L1 gas' }
      : gasTier === 'alt-l1'
        ? { setup: 0.2, weekly: 0.05, total: 1, label: 'under $0.25 network gas' }
        : { setup: 0.5, weekly: 0.15, total: 2, label: 'under $0.75 L2 gas' };
    const capital = row.tvl_usd >= 1e9 ? 350 : row.tvl_usd >= 250e6 ? 200 : row.tvl_usd >= 50e6 ? 100 : 50;
    const hold = row.age_days === null ? 45 : row.age_days < 180 ? 60 : row.age_days < 365 ? 45 : 30;
    const weeks = Math.max(4, Math.ceil(hold / 7));
    const cat = (row.category || '').toLowerCase();
    const n = row.name;

    let core = {
      title: 'Deploy core protocol position',
      action: `Deposit $${capital} USDC into ${n}'s primary product on ${primary} and keep the position active across snapshots.`,
    };
    if (cat.includes('risk curator') || cat.includes('allocator') || cat.includes('cdp manager')) {
      core = { title: 'Deposit into curated vault', action: `Deposit $${capital} USDC into ${n}'s flagship curated vault on ${primary} and retain the vault receipt token in your wallet.` };
    } else if (cat.includes('rwa')) {
      core = { title: 'Mint yield-bearing RWA', action: `Mint or subscribe $${capital} into ${n}'s yield-bearing RWA token on ${primary} and hold it in self-custody.` };
    } else if (cat.includes('basis') || cat.includes('yield')) {
      core = { title: 'Enter core yield strategy', action: `Deploy $${capital} USDC into ${n}'s primary yield or basis vault on ${primary} and keep shares staked through epoch rollovers.` };
    } else if (cat.includes('lend') || cat.includes('cdp') || cat.includes('collateral')) {
      core = { title: 'Supply collateral & borrow lightly', action: `Supply $${capital} USDC or blue-chip collateral on ${n} (${primary}) and borrow 20% against it to register active borrower usage.` };
    } else if (cat.includes('dex') || cat.includes('liquidity')) {
      core = { title: 'Provide LP & execute swaps', action: `Provide $${capital} in a core stable or blue-chip pool on ${n} (${primary}) and execute 2-3 organic spot swaps.` };
    } else if (cat.includes('derivative') || cat.includes('perpetual') || cat.includes('prediction') || cat.includes('otc')) {
      core = { title: 'Post margin & generate volume', action: `Deposit $${capital} USDC margin on ${n} (${primary}) and open small delta-neutral or hedged positions to log real volume.` };
    } else if (cat.includes('restak') || cat.includes('staking')) {
      core = { title: 'Stake native receipt asset', action: `Deposit $${capital} of the native staking asset into ${n} on ${primary} and keep the receipt position delegated.` };
    } else if (cat.includes('payment') || cat.includes('stable') || cat.includes('cedefi')) {
      core = { title: 'Mint & transact stable balance', action: `Mint or fund $${capital} through ${n} on ${primary} and complete at least two on-chain transfers or settlement actions.` };
    } else if (cat.includes('insurance')) {
      core = { title: 'Underwrite or purchase cover', action: `Commit $${capital} to ${n}'s underwriting pool or purchase a small cover policy on ${primary} and hold it to expiry.` };
    }

    const hasDrawdown = typeof row.change_7d === 'number' && row.change_7d <= -5;
    const steps = [
      {
        title: 'Isolate wallet & fund gas',
        action: `Create a dedicated farming wallet on ${primary}, fund it with $${capital} principal plus native gas, and keep zero unrelated approvals on it.`,
        cost: `${gas.label} for initial funding`,
        time: '10 minutes',
      },
      {
        title: core.title,
        action: core.action,
        cost: `$${capital} refundable capital + ${gas.label}`,
        time: '15 minutes',
      },
      secondary
        ? {
            title: 'Multi-chain footprint & weekly cadence',
            action: `Repeat one qualifying interaction weekly on ${primary} (and optionally mirror 20% of size on ${secondary}) so activity spans ${weeks}+ distinct weeks.`,
            cost: `~$${(gas.weekly * weeks).toFixed(2)} cumulative gas over ${weeks} weeks`,
            time: `10 min/week (${weeks} weeks)`,
          }
        : {
            title: 'Weekly organic cadence',
            action: `Execute one qualifying on-chain action weekly on ${primary} (top-up, compound, swap, or rebalance) to avoid single-tx sybil filters.`,
            cost: `~$${(gas.weekly * weeks).toFixed(2)} cumulative gas over ${weeks} weeks`,
            time: `10 min/week (${weeks} weeks)`,
          },
      hasDrawdown
        ? {
            title: 'Monitor 7d TVL drawdown & hold window',
            action: `TVL moved ${row.change_7d.toFixed(1)}% over 7d; verify pool liquidity health before scaling, then hold the $${capital} position for ${hold} days across snapshot epochs.`,
            cost: `$${capital} principal remains refundable (monitor slippage)`,
            time: `${hold}-day holding window (5 min weekly check)`,
          }
        : {
            title: 'Hold across snapshot epochs',
            action: `Maintain the $${capital} position uninterrupted for at least ${hold} days so time-weighted points and multi-epoch snapshots register full weight.`,
            cost: `$${capital} principal stays refundable in position`,
            time: `${hold}-day holding window`,
          },
      {
        title: 'Verify points & official claim route',
        action: `Check ${n}'s official points dashboard before unwinding; never sign blind permits or pay third-party claim fees.`,
        cost: '$0 verification fee (never pay to claim)',
        time: '10 minutes',
      },
      {
        title: 'Log tx hashes & unwind cleanly',
        action: `Record wallet address, deposit/withdraw tx hashes, and epoch dates in your farm ledger, then revoke token allowances after exiting.`,
        cost: `${gas.label} for exit and revoke`,
        time: '10 minutes',
      },
    ];

    return { primary, secondary, gasTier, capital, estGas: gas.total, hold, steps };
  }

  function isSandboxModified() {
    return Object.keys(DATA.params).some((k) => Math.abs(state.params[k] - DATA.params[k]) > 1e-6);
  }

  function getScoredRows() {
    const cal = isSandboxModified()
      ? calibrateCategoryMultiples(DATA.live, state.params)
      : DATA.calibration;
    const computed = DATA.rows.map((r) => computeImpliedValue(r, cal, state.params));
    computed.sort((a, b) => b.implied_value_usd - a.implied_value_usd || b.tvl_usd - a.tvl_usd || a.slug.localeCompare(b.slug));
    computed.forEach((r, i) => { r.rank = i + 1; });
    return { rows: computed, calibration: cal };
  }

  function filterAndSortRows(rows) {
    const q = state.search.trim().toLowerCase();
    const filtered = rows.filter((r) => {
      if (state.tier !== 'all' && r.tier !== state.tier) return false;
      if (state.category !== 'all' && (r.category || 'Uncategorized') !== state.category) return false;
      if (state.chain !== 'all' && !r.chains.includes(state.chain)) return false;
      if (state.momentum === 'pos' && !(typeof r.change_7d === 'number' && r.change_7d > 0)) return false;
      if (state.momentum === 'fast' && !(typeof r.change_7d === 'number' && r.change_7d >= 5)) return false;
      if (state.momentum === 'neg' && !(typeof r.change_7d === 'number' && r.change_7d < 0)) return false;
      if (q) {
        const hay = `${r.name} ${r.slug} ${r.category || ''} ${r.chains.join(' ')}`.toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    });

    const dir = state.sortDir === 'asc' ? 1 : -1;
    const key = state.sortKey;
    filtered.sort((a, b) => {
      let va; let vb;
      if (key === 'name' || key === 'category') {
        va = (a[key] || '').toLowerCase();
        vb = (b[key] || '').toLowerCase();
        return va < vb ? -dir : va > vb ? dir : a.rank - b.rank;
      }
      if (key === 'change_7d') {
        va = a.change_7d === null ? -9999 : a.change_7d;
        vb = b.change_7d === null ? -9999 : b.change_7d;
      } else if (key === 'age_days') {
        va = a.age_days === null ? -1 : a.age_days;
        vb = b.age_days === null ? -1 : b.age_days;
      } else {
        va = a[key] ?? 0;
        vb = b[key] ?? 0;
      }
      if (va !== vb) return (va - vb) * dir;
      return a.rank - b.rank;
    });
    return filtered;
  }

  function buildFilterOptions(rows) {
    const catCounts = new Map();
    const chainCounts = new Map();
    for (const r of rows) {
      const cat = r.category || 'Uncategorized';
      catCounts.set(cat, (catCounts.get(cat) || 0) + 1);
      for (const c of r.chains) chainCounts.set(c, (chainCounts.get(c) || 0) + 1);
    }
    return {
      categories: [...catCounts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])),
      chains: [...chainCounts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])),
    };
  }

  function hasActiveFilters() {
    return state.tier !== 'all' || state.category !== 'all' || state.chain !== 'all' || state.momentum !== 'all' || state.search.trim() !== '';
  }

  function sortButton(key, label) {
    const active = state.sortKey === key;
    const arrow = active ? (state.sortDir === 'asc' ? ' ▲' : ' ▼') : '';
    return `<button type="button" class="${active ? 'sorted' : ''}" data-sort="${key}">${label}${arrow}</button>`;
  }

  function renderHeader() {
    return `
      <header class="topbar">
        <div class="brand-group">
          <div class="radar-mark" aria-hidden="true">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#10b981" stroke-width="1.8">
              <circle cx="12" cy="12" r="9" opacity="0.35"/>
              <circle cx="12" cy="12" r="5" opacity="0.65"/>
              <path d="M12 12L18.5 5.5" stroke-linecap="round"/>
              <circle cx="12" cy="12" r="2" fill="#10b981"/>
            </svg>
          </div>
          <div>
            <div class="brand-title">Launch Radar <span class="version-tag">${esc(DATA.model_version)}</span></div>
            <div class="brand-sub">Peer-calibrated pre-token valuation &amp; costed farm planner · Snapshot ${esc(DATA.as_of)}</div>
          </div>
        </div>
        <div class="top-nav">
          <div class="nav-tabs" role="tablist" aria-label="Dashboard views">
            <button type="button" data-view="radar" aria-pressed="${state.view === 'radar'}">Pre-Token Radar (${DATA.universe.board_count})</button>
            <button type="button" data-view="live" aria-pressed="${state.view === 'live'}">Live Market Comps (${DATA.universe.live_count})</button>
            <button type="button" data-view="model" aria-pressed="${state.view === 'model'}">Model &amp; Calibration</button>
          </div>
          <div class="snapshot-pill">Watchlist floor ${fmtUsd(DATA.floor_usd)}</div>
        </div>
      </header>
    `;
  }

  function renderKpis(allRows, visibleRows, cal) {
    const active = hasActiveFilters();
    const scope = active ? visibleRows : allRows;
    const totalImplied = scope.reduce((s, r) => s + r.implied_value_usd, 0);
    const totalTvl = scope.reduce((s, r) => s + r.tvl_usd, 0);
    const wlCount = scope.filter((r) => r.tier === 'watchlist').length;
    const earlyCount = scope.length - wlCount;
    const topMover = [...scope].filter((r) => typeof r.change_7d === 'number').sort((a, b) => b.change_7d - a.change_7d)[0];

    return `
      <section class="kpi-grid" aria-label="Summary metrics">
        <div class="kpi-card">
          <span class="kpi-label">${active ? 'Filtered Implied Value' : 'Total Pre-Token Implied'}</span>
          <span class="kpi-val emerald">${fmtUsd(totalImplied)}</span>
          <span class="kpi-sub">${scope.length} pre-token protocols · ${fmtUsd(totalTvl)} TVL</span>
        </div>
        <div class="kpi-card">
          <span class="kpi-label">Watchlist Coverage</span>
          <span class="kpi-val">${DATA.universe.watchlist_count}/${DATA.universe.watchlist_count}</span>
          <span class="kpi-sub">${active ? `${wlCount} in filter · ${earlyCount} early radar` : `100% floor + ${DATA.universe.early_count} early radar`}</span>
        </div>
        <div class="kpi-card">
          <span class="kpi-label">Live Comps Median</span>
          <span class="kpi-val">${cal.global_median.toFixed(3)}x</span>
          <span class="kpi-sub">Empirical MCap/TVL (${cal.live_peer_count} live DeFi peers)</span>
        </div>
        <div class="kpi-card">
          <span class="kpi-label">IQR Valuation Band</span>
          <span class="kpi-val">${cal.global_p25.toFixed(2)}x–${cal.global_p75.toFixed(2)}x</span>
          <span class="kpi-sub">Peer P25 Bear to P75 Bull shrinkage</span>
        </div>
        <div class="kpi-card">
          <span class="kpi-label">Fastest 7d Inflow</span>
          <span class="kpi-val">${topMover ? fmtPct(topMover.change_7d) : '—'}</span>
          <span class="kpi-sub">${topMover ? `${esc(topMover.name)} (${fmtUsd(topMover.implied_value_usd)})` : 'No 7d flow in filter'}</span>
        </div>
      </section>
    `;
  }

  function renderFormulaBar() {
    const p = state.params;
    const modified = isSandboxModified();
    return `
      <section class="formula-bar">
        <div class="formula-eq">
          <strong>Implied</strong> = TVL × <strong>M_sector</strong>(EB k=${p.shrinkage_k}) × (1 + ${p.growth_weight}·tanh(Δ7d/${p.growth_scale})) × (${p.maturity_floor} + ${p.maturity_range}·√(age/1095)) × (1 + ${p.chain_weight}·ln(chains))
        </div>
        <div class="formula-actions">
          ${modified ? '<button type="button" class="btn-ghost" data-action="reset-model">Reset model</button>' : ''}
          <button type="button" class="btn-ghost ${state.sandboxOpen ? 'active' : ''}" data-action="toggle-sandbox">
            ${state.sandboxOpen ? 'Hide Sandbox' : 'Model Sandbox'}
          </button>
        </div>
      </section>
      ${state.sandboxOpen ? `
        <section class="sandbox-panel" aria-label="Interactive model parameters">
          <label class="slider-field">
            <span class="slider-head"><span>Shrinkage Prior (k)</span><b>${p.shrinkage_k}</b></span>
            <input type="range" min="1" max="15" step="1" value="${p.shrinkage_k}" data-param="shrinkage_k">
          </label>
          <label class="slider-field">
            <span class="slider-head"><span>7d Growth Weight</span><b>${p.growth_weight.toFixed(2)}</b></span>
            <input type="range" min="0" max="0.6" step="0.05" value="${p.growth_weight}" data-param="growth_weight">
          </label>
          <label class="slider-field">
            <span class="slider-head"><span>Maturity Range</span><b>${p.maturity_range.toFixed(2)}</b></span>
            <input type="range" min="0" max="0.7" step="0.05" value="${p.maturity_range}" data-param="maturity_range">
          </label>
          <label class="slider-field">
            <span class="slider-head"><span>Multi-Chain Weight</span><b>${p.chain_weight.toFixed(2)}</b></span>
            <input type="range" min="0" max="0.12" step="0.01" value="${p.chain_weight}" data-param="chain_weight">
          </label>
          <button type="button" class="btn-ghost" data-action="reset-model">Defaults</button>
        </section>
      ` : ''}
    `;
  }

  function renderToolbar(allRows, visibleRows) {
    const opts = buildFilterOptions(allRows);
    const chips = [];
    if (state.tier !== 'all') chips.push({ key: 'tier', label: `Tier: ${state.tier === 'watchlist' ? 'Watchlist ≥$50M' : 'Early Radar <$50M'}` });
    if (state.category !== 'all') chips.push({ key: 'category', label: `Sector: ${state.category}` });
    if (state.chain !== 'all') chips.push({ key: 'chain', label: `Chain: ${state.chain}` });
    if (state.momentum !== 'all') {
      const mLabel = { pos: '7d Flow > 0%', fast: '7d Flow ≥ +5%', neg: '7d Drawdown < 0%' }[state.momentum];
      chips.push({ key: 'momentum', label: mLabel });
    }
    if (state.search.trim()) chips.push({ key: 'search', label: `Query: "${state.search.trim()}"` });

    return `
      <section class="toolbar" aria-label="Board filters">
        <div class="tier-pills" role="group" aria-label="Tier filter">
          <button type="button" data-tier="all" aria-pressed="${state.tier === 'all'}">All (${allRows.length})</button>
          <button type="button" data-tier="watchlist" aria-pressed="${state.tier === 'watchlist'}">Watchlist (${DATA.universe.watchlist_count})</button>
          <button type="button" data-tier="early" aria-pressed="${state.tier === 'early'}">Early Radar (${DATA.universe.early_count})</button>
        </div>
        <input type="search" class="ctrl-input" id="search-input" placeholder="Filter protocol, slug, sector, chain…" value="${esc(state.search)}" aria-label="Search protocols">
        <select class="ctrl-select" id="cat-select" aria-label="Filter by sector">
          <option value="all">All Sectors (${opts.categories.length})</option>
          ${opts.categories.map(([c, n]) => `<option value="${esc(c)}" ${state.category === c ? 'selected' : ''}>${esc(c)} (${n})</option>`).join('')}
        </select>
        <select class="ctrl-select" id="chain-select" aria-label="Filter by chain">
          <option value="all">All Chains (${opts.chains.length})</option>
          ${opts.chains.map(([c, n]) => `<option value="${esc(c)}" ${state.chain === c ? 'selected' : ''}>${esc(c)} (${n})</option>`).join('')}
        </select>
        <select class="ctrl-select" id="mom-select" aria-label="Filter by 7d momentum">
          <option value="all" ${state.momentum === 'all' ? 'selected' : ''}>Any 7d Flow</option>
          <option value="pos" ${state.momentum === 'pos' ? 'selected' : ''}>Positive (&gt; 0%)</option>
          <option value="fast" ${state.momentum === 'fast' ? 'selected' : ''}>Accelerating (≥ +5%)</option>
          <option value="neg" ${state.momentum === 'neg' ? 'selected' : ''}>Drawdown (&lt; 0%)</option>
        </select>
        <div class="toolbar-right">
          <span class="row-counter">Showing ${visibleRows.length} of ${allRows.length}</span>
          ${chips.length ? '<button type="button" class="btn-ghost" data-action="reset-filters">Clear all</button>' : ''}
        </div>
      </section>
      ${chips.length ? `
        <div class="filter-chips" aria-label="Active filters">
          ${chips.map((c) => `<span class="chip">${esc(c.label)} <button type="button" data-clear="${c.key}" aria-label="Remove filter">×</button></span>`).join('')}
        </div>
      ` : ''}
    `;
  }

  function renderRadarTable(visibleRows, maxImplied) {
    if (!visibleRows.length) {
      return '<div class="panel"><div class="empty-state"><h3>No matching pre-token protocols</h3><p>Adjust your search or clear active filters to inspect the full radar.</p></div></div>';
    }
    const rowsHtml = visibleRows.map((r) => {
      const pctBar = Math.max(3, Math.round((Math.log10(Math.max(1, r.implied_value_usd)) / Math.log10(Math.max(10, maxImplied))) * 100));
      const flowClass = r.change_7d === null ? 'flow-na' : r.change_7d >= 0 ? 'flow-pos' : 'flow-neg';
      const chainsShown = r.chains.slice(0, 2).map((c) => `<span class="chain-tag">${esc(c)}</span>`).join('')
        + (r.chains.length > 2 ? `<span class="chain-tag">+${r.chains.length - 2}</span>` : '');
      return `
        <tr data-slug="${esc(r.slug)}" data-selected="${state.selectedSlug === r.slug}" tabindex="0">
          <td class="rank-cell ${r.rank <= 10 ? 'rank-top' : ''}">#${r.rank}</td>
          <td>
            <div class="proto-cell">
              <div class="proto-name">
                ${esc(r.name)}
                <span class="badge ${r.tier === 'watchlist' ? 'badge-wl' : 'badge-early'}">${r.tier === 'watchlist' ? 'WATCHLIST' : 'EARLY'}</span>
              </div>
              <div class="proto-meta"><span>${esc(r.category || 'Uncategorized')}</span><span>·</span><span class="mono">${esc(r.slug)}</span></div>
            </div>
          </td>
          <td><div class="chains-list">${chainsShown || '<span class="chain-tag">Multi</span>'}</div></td>
          <td class="r mono">${fmtUsd(r.tvl_usd)}</td>
          <td class="r mono ${flowClass}">${fmtPct(r.change_7d)}</td>
          <td class="r mono">${fmtAge(r.age_days)}</td>
          <td class="r mono">${r.base_multiple.toFixed(2)}x<div class="proto-meta" style="justify-content:flex-end">${r.peer_count ? `${r.peer_count} ${r.peer_count === 1 ? 'peer' : 'peers'}` : 'global'}</div></td>
          <td class="r">
            <div class="val-cell">
              <span class="val-main">${fmtUsd(r.implied_value_usd)}</span>
              <div class="val-bar"><i style="width:${pctBar}%"></i></div>
              <span class="val-range">${fmtUsd(r.bear_value_usd)} – ${fmtUsd(r.bull_value_usd)}</span>
            </div>
          </td>
          <td class="r"><span class="farm-pill">$${r.capital_usd} · ~$${r.est_gas_usd} gas · ${r.hold_days}d</span></td>
        </tr>
      `;
    }).join('');

    return `
      <section class="panel">
        <div class="table-wrap">
          <table>
            <thead>
              <tr>
                <th>${sortButton('rank', 'Rank')}</th>
                <th>${sortButton('name', 'Protocol & Sector')}</th>
                <th>Chains</th>
                <th class="r">${sortButton('tvl_usd', 'TVL')}</th>
                <th class="r">${sortButton('change_7d', '7d Flow')}</th>
                <th class="r">${sortButton('age_days', 'Age')}</th>
                <th class="r">${sortButton('base_multiple', 'Sector Mult')}</th>
                <th class="r">${sortButton('implied_value_usd', 'Implied Value (Bear–Bull)')}</th>
                <th class="r">Farm Plan</th>
              </tr>
            </thead>
            <tbody>${rowsHtml}</tbody>
          </table>
        </div>
      </section>
    `;
  }

  function renderLiveCompsView() {
    const rowsHtml = DATA.live.map((p, i) => {
      const flowClass = p.change_7d === null ? 'flow-na' : p.change_7d >= 0 ? 'flow-pos' : 'flow-neg';
      return `
        <tr>
          <td class="rank-cell">${i + 1}</td>
          <td>
            <div class="proto-cell">
              <div class="proto-name">${esc(p.name)} <span class="badge badge-live">${esc(p.symbol || 'LIVE')}</span></div>
              <div class="proto-meta">${esc(p.category || 'Other')} · <span class="mono">${esc(p.slug)}</span></div>
            </div>
          </td>
          <td class="r mono">${fmtUsd(p.mcap_usd)}</td>
          <td class="r mono">${fmtUsd(p.tvl_usd)}</td>
          <td class="r mono" style="color:var(--cyan);font-weight:700">${p.mcap_tvl_ratio.toFixed(3)}x</td>
          <td class="r mono ${flowClass}">${fmtPct(p.change_7d)}</td>
          <td><div class="chains-list">${p.chains.slice(0, 3).map((c) => `<span class="chain-tag">${esc(c)}</span>`).join('')}</div></td>
        </tr>
      `;
    }).join('');

    return `
      <section class="panel" style="margin-top:12px">
        <div style="padding:12px 16px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px">
          <div>
            <h2 style="font-size:15px">Live-Token Market Comparables (Separated from Pre-Token Board)</h2>
            <p style="font-size:12px;color:var(--muted);margin-top:2px">These ${DATA.live.length} trading DeFi protocols are never mixed into pre-token ranks; their observed MCap/TVL ratios calibrate each sector's base multiple.</p>
          </div>
          <span class="badge badge-live">Global Median ${DATA.calibration.global_median.toFixed(3)}x</span>
        </div>
        <div class="table-wrap">
          <table>
            <thead>
              <tr>
                <th>#</th>
                <th>Live Protocol &amp; Ticker</th>
                <th class="r">Market Cap</th>
                <th class="r">TVL</th>
                <th class="r">MCap / TVL</th>
                <th class="r">7d Flow</th>
                <th>Chains</th>
              </tr>
            </thead>
            <tbody>${rowsHtml}</tbody>
          </table>
        </div>
      </section>
    `;
  }

  function renderModelView(cal) {
    const cats = Object.values(cal.categories).sort((a, b) => b.peer_count - a.peer_count || a.category.localeCompare(b.category));
    const catRows = cats.map((c) => `
      <tr>
        <td><b>${esc(c.category)}</b></td>
        <td class="r mono">${c.peer_count}</td>
        <td class="r mono">${c.raw_median === null ? '—' : `${c.raw_median.toFixed(3)}x`}</td>
        <td class="r mono" style="color:var(--amber)">${c.bear_multiple.toFixed(3)}x</td>
        <td class="r mono" style="color:var(--emerald);font-weight:700">${c.base_multiple.toFixed(3)}x</td>
        <td class="r mono" style="color:var(--cyan)">${c.bull_multiple.toFixed(3)}x</td>
      </tr>
    `).join('');

    return `
      <section class="two-col">
        <div class="card">
          <h2>Empirical-Bayes Peer Calibration Formula</h2>
          <p>Every valuation is computed deterministically from the sealed DefiLlama snapshot with zero hardcoded protocol names. Live-token DeFi protocols calibrate each sector's MCap/TVL multiple via Empirical-Bayes shrinkage toward the global live median (${cal.global_median.toFixed(3)}x).</p>
          <div class="code-block">M_sector(c) = clamp(exp((n_c·ln(med_c) + k·ln(M_global)) / (n_c + k)), 0.08, 0.85)
growth_mult = 1 + ${state.params.growth_weight} * tanh(change_7d / ${state.params.growth_scale})
mat_mult    = ${state.params.maturity_floor} + ${state.params.maturity_range} * sqrt(min(age_days, 1095) / 1095)
chain_mult  = 1 + ${state.params.chain_weight} * min(ln(max(1, chains.length)), 2.5)
implied_usd = round(tvl_usd * M_sector(c) * growth_mult * mat_mult * chain_mult)</div>
          <p style="margin-top:10px"><strong>Universe hygiene:</strong> All ${DATA.universe.watchlist_count} house watchlist protocols are guaranteed coverage. Below the ${fmtUsd(DATA.floor_usd)} floor, ${DATA.universe.early_count} clean pre-token protocols are added while ${DATA.universe.excluded_non_launch_count} CEXs, bridges, liquid-staked wrappers, and versioned pools are excluded.</p>
        </div>
        <div class="card" style="padding:0;overflow:hidden">
          <div style="padding:14px 16px;border-bottom:1px solid var(--border)">
            <h2 style="margin:0">Sector Multiple Calibration (${cal.live_peer_count} Live Peers)</h2>
          </div>
          <div class="table-wrap" style="max-height:420px;overflow-y:auto">
            <table>
              <thead>
                <tr>
                  <th>Sector</th>
                  <th class="r">Peers</th>
                  <th class="r">Raw Med</th>
                  <th class="r">Bear (P25)</th>
                  <th class="r">Base (EB)</th>
                  <th class="r">Bull (P75)</th>
                </tr>
              </thead>
              <tbody>${catRows}</tbody>
            </table>
          </div>
        </div>
      </section>
    `;
  }

  function renderDetailDrawer(allRows, visibleRows) {
    if (!state.selectedSlug) return '';
    const row = allRows.find((r) => r.slug === state.selectedSlug);
    if (!row) return '';
    const plan = buildFarmPlan(row);
    const idx = visibleRows.findIndex((r) => r.slug === row.slug);
    const prevSlug = idx > 0 ? visibleRows[idx - 1].slug : null;
    const nextSlug = idx >= 0 && idx < visibleRows.length - 1 ? visibleRows[idx + 1].slug : null;

    const span = Math.max(1, row.bull_value_usd - row.bear_value_usd);
    const basePos = clamp(((row.implied_value_usd - row.bear_value_usd) / span) * 84 + 8, 10, 90);
    const sectorPeers = DATA.live.filter((p) => p.category === row.category).slice(0, 4);

    return `
      <div class="drawer-backdrop" data-action="close-drawer">
        <aside class="drawer" role="dialog" aria-modal="true" aria-label="${esc(row.name)} valuation and farm plan">
          <div class="drawer-head">
            <div>
              <div class="drawer-title">
                <span>#${row.rank} ${esc(row.name)}</span>
                <span class="badge ${row.tier === 'watchlist' ? 'badge-wl' : 'badge-early'}">${row.tier === 'watchlist' ? 'WATCHLIST' : 'EARLY RADAR'}</span>
              </div>
              <div class="drawer-sub">${esc(row.category || 'Uncategorized')} · ${esc(row.slug)} · Listed ${esc(row.listed_at || 'unreported')} (${fmtAge(row.age_days)})</div>
            </div>
            <div class="drawer-nav">
              <button type="button" class="btn-ghost" ${prevSlug ? `data-open="${esc(prevSlug)}"` : 'disabled'} aria-label="Previous protocol">↑</button>
              <button type="button" class="btn-ghost" ${nextSlug ? `data-open="${esc(nextSlug)}"` : 'disabled'} aria-label="Next protocol">↓</button>
              <button type="button" class="btn-ghost" data-action="close-drawer">Close</button>
            </div>
          </div>

          <section class="drawer-section">
            <div class="section-label">
              <span>Implied Launch Valuation Band</span>
              <span class="mono">${row.peer_count ? `${row.peer_count} live sector peers` : 'Global live median fallback'}</span>
            </div>
            <div class="band-box">
              <div class="band-nums">
                <div><small>Bear (P25)</small><strong>${fmtUsd(row.bear_value_usd)}</strong></div>
                <div><small>Base Implied</small><strong class="base-v">${fmtUsd(row.implied_value_usd)}</strong></div>
                <div><small>Bull (P75)</small><strong>${fmtUsd(row.bull_value_usd)}</strong></div>
              </div>
              <div class="band-track">
                <div class="band-fill"></div>
                <div class="band-dot" style="left:${basePos.toFixed(1)}%"></div>
              </div>
            </div>
            <div class="eq-grid">
              <div class="eq-row"><span>1. Snapshot TVL (${row.chains.length} chain${row.chains.length === 1 ? '' : 's'})</span><b>${fmtUsd(row.tvl_usd)}</b></div>
              <div class="eq-row"><span>2. Sector Base Multiple (EB k=${state.params.shrinkage_k})</span><b>× ${row.base_multiple.toFixed(4)}</b></div>
              <div class="eq-row"><span>3. 7d Momentum (${fmtPct(row.change_7d)})</span><b>× ${row.growth_multiplier.toFixed(4)}</b></div>
              <div class="eq-row"><span>4. Pre-Token Maturity (${fmtAge(row.age_days)})</span><b>× ${row.maturity_multiplier.toFixed(4)}</b></div>
              <div class="eq-row"><span>5. Multi-Chain Breadth (${row.chains.slice(0, 3).join(', ')}${row.chains.length > 3 ? '…' : ''})</span><b>× ${row.chain_multiplier.toFixed(4)}</b></div>
              <div class="eq-row total"><span>Implied Pre-Token Value</span><b>${fmtUsd(row.implied_value_usd)}</b></div>
            </div>
          </section>

          <section class="drawer-section">
            <div class="section-label">
              <span>Actionable 6-Step Farm Plan</span>
              <span class="mono">Primary: ${esc(plan.primary)} (${plan.gasTier})</span>
            </div>
            <div class="farm-meta-strip">
              <div class="farm-stat"><small>Refundable Capital</small><b>$${plan.capital}</b></div>
              <div class="farm-stat"><small>Est. Non-Ref Gas</small><b>~$${plan.estGas}</b></div>
              <div class="farm-stat"><small>Hold Window</small><b>${plan.hold} days</b></div>
            </div>
            <ol class="steps-list">
              ${plan.steps.map((s, i) => `
                <li class="step-item">
                  <div class="step-num">${i + 1}</div>
                  <div>
                    <div class="step-title">${esc(s.title)}</div>
                    <div class="step-action">${esc(s.action)}</div>
                    <div class="step-tags">
                      <span class="step-cost">Cost: ${esc(s.cost)}</span>
                      <span class="step-time">Time: ${esc(s.time)}</span>
                    </div>
                  </div>
                </li>
              `).join('')}
            </ol>
          </section>

          ${sectorPeers.length ? `
            <section class="drawer-section">
              <div class="section-label"><span>Live ${esc(row.category)} Comparables in Snapshot</span><span class="mono">Observed MCap/TVL</span></div>
              <div class="peers-mini">
                ${sectorPeers.map((p) => `
                  <div class="peer-row">
                    <span><b>${esc(p.name)}</b> <span class="badge badge-live">${esc(p.symbol || 'LIVE')}</span></span>
                    <span class="mono">${fmtUsd(p.mcap_usd)} / ${fmtUsd(p.tvl_usd)} = <b style="color:var(--cyan)">${p.mcap_tvl_ratio.toFixed(2)}x</b></span>
                  </div>
                `).join('')}
              </div>
            </section>
          ` : ''}
        </aside>
      </div>
    `;
  }

  function render() {
    const { rows: allRows, calibration } = getScoredRows();
    const visibleRows = filterAndSortRows(allRows);
    const maxImplied = allRows.length ? allRows[0].implied_value_usd : 1;

    let bodyHtml = '';
    if (state.view === 'radar') {
      bodyHtml = renderKpis(allRows, visibleRows, calibration)
        + renderFormulaBar()
        + renderToolbar(allRows, visibleRows)
        + renderRadarTable(visibleRows, maxImplied);
    } else if (state.view === 'live') {
      bodyHtml = renderKpis(allRows, visibleRows, calibration) + renderLiveCompsView();
    } else {
      bodyHtml = renderKpis(allRows, visibleRows, calibration) + renderFormulaBar() + renderModelView(calibration);
    }

    ROOT.innerHTML = renderHeader() + bodyHtml + `
      <footer class="footer-note">
        <span>Data: ${esc(DATA.source)} · Pre-token status reflects DefiLlama's snapshot record, never a launch guarantee.</span>
        <span>${DATA.universe.board_count} pre-token ranked · ${DATA.universe.live_count} live comps separated · ${DATA.universe.excluded_non_launch_count} wrapped/CEX/bridge excluded</span>
      </footer>
    ` + renderDetailDrawer(allRows, visibleRows);

    bindEvents();
  }

  function bindEvents() {
    ROOT.querySelectorAll('[data-view]').forEach((el) => {
      el.addEventListener('click', () => { state.view = el.dataset.view; state.selectedSlug = null; render(); });
    });
    ROOT.querySelectorAll('[data-tier]').forEach((el) => {
      el.addEventListener('click', () => { state.tier = el.dataset.tier; render(); });
    });
    ROOT.querySelectorAll('[data-sort]').forEach((el) => {
      el.addEventListener('click', () => {
        const key = el.dataset.sort;
        if (state.sortKey === key) state.sortDir = state.sortDir === 'asc' ? 'desc' : 'asc';
        else { state.sortKey = key; state.sortDir = key === 'rank' || key === 'name' ? 'asc' : 'desc'; }
        render();
      });
    });
    ROOT.querySelectorAll('tbody tr[data-slug]').forEach((el) => {
      el.addEventListener('click', () => { state.selectedSlug = el.dataset.slug; render(); });
      el.addEventListener('keydown', (ev) => {
        if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); state.selectedSlug = el.dataset.slug; render(); }
      });
    });
    ROOT.querySelectorAll('[data-open]').forEach((el) => {
      el.addEventListener('click', (ev) => { ev.stopPropagation(); state.selectedSlug = el.dataset.open; render(); });
    });
    ROOT.querySelectorAll('[data-action="close-drawer"]').forEach((el) => {
      el.addEventListener('click', (ev) => {
        if (ev.target === el) { state.selectedSlug = null; render(); }
      });
    });
    ROOT.querySelectorAll('[data-action="toggle-sandbox"]').forEach((el) => {
      el.addEventListener('click', () => { state.sandboxOpen = !state.sandboxOpen; render(); });
    });
    ROOT.querySelectorAll('[data-action="reset-model"]').forEach((el) => {
      el.addEventListener('click', () => { state.params = { ...DATA.params }; render(); });
    });
    ROOT.querySelectorAll('[data-action="reset-filters"]').forEach((el) => {
      el.addEventListener('click', () => {
        state.tier = 'all'; state.category = 'all'; state.chain = 'all'; state.momentum = 'all'; state.search = '';
        render();
      });
    });
    ROOT.querySelectorAll('[data-clear]').forEach((el) => {
      el.addEventListener('click', () => {
        const k = el.dataset.clear;
        state[k] = k === 'search' ? '' : 'all';
        render();
      });
    });
    ROOT.querySelectorAll('[data-param]').forEach((el) => {
      el.addEventListener('input', () => { state.params[el.dataset.param] = Number(el.value); render(); });
    });

    const searchEl = document.getElementById('search-input');
    if (searchEl) {
      searchEl.addEventListener('input', (ev) => {
        const pos = ev.target.selectionStart;
        state.search = ev.target.value;
        render();
        const next = document.getElementById('search-input');
        if (next) { next.focus(); next.setSelectionRange(pos, pos); }
      });
    }
    const catEl = document.getElementById('cat-select');
    if (catEl) catEl.addEventListener('change', (ev) => { state.category = ev.target.value; render(); });
    const chainEl = document.getElementById('chain-select');
    if (chainEl) chainEl.addEventListener('change', (ev) => { state.chain = ev.target.value; render(); });
    const momEl = document.getElementById('mom-select');
    if (momEl) momEl.addEventListener('change', (ev) => { state.momentum = ev.target.value; render(); });
  }

  window.addEventListener('keydown', (ev) => {
    if (ev.key === 'Escape' && state.selectedSlug) { state.selectedSlug = null; render(); }
  });

  render();
})();
